export function monitorLinkKey(portal,username){if(!portal||!username)throw Error('Sign in before saving a monitoring link.');return 'reg.monitor.link.v1:'+JSON.stringify([portal,username]);}
export function validateMonitorLink(link){
 if(link?.version!==1||typeof link.name!=='string'||!['creator','editor'].includes(link.role)||![60000,300000,900000].includes(link.interval)||!Array.isArray(link.users)||(!link.users.length&&!link.allUsers)||!link.users.every(user=>typeof user==='string'&&user.trim())||!Array.isArray(link.layers)||!link.layers.length)throw Error('The saved monitoring link is invalid. Save a new link.');
 for(const layer of link.layers){let url;try{url=new URL(layer.url);}catch{throw Error('The saved layer URL is invalid.');}if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||typeof layer.source!=='string'||!layer.source||!Array.isArray(layer.required)||!layer.required.every(field=>typeof field==='string'))throw Error('The saved layer configuration is invalid.');}return link;
}
export function saveMonitorLink(storage,key,link){validateMonitorLink(link);const data={allUsers:link.allUsers===true,version:1,name:link.name,role:link.role,interval:link.interval,users:[...new Set(link.users)],layers:link.layers.map(layer=>({url:layer.url,source:layer.source,collectedField:typeof layer.collectedField==='string'?layer.collectedField:undefined,required:[...new Set(layer.required)],space:layer.space}))};storage.setItem(key,JSON.stringify(data));return data;}
export function readMonitorLink(storage,key){const raw=storage.getItem(key);if(!raw)throw Error('No saved monitoring link for this portal account in this browser.');return validateMonitorLink(JSON.parse(raw));}
